import java.util.Scanner;

public class Main {
    static long INF = 17446744073709551616L;
    static long mod, n, k;
    static long[][] dp = new long[18][250005];
    static long[] factorial = new long[250005];
    static long[] invFactorial = new long[250005];

    static long fastPow(long base, long exponent) {
        long result = 1L;
        long current = base;
        while (exponent > 0) {
            if ((exponent & 1L) == 1L) {
                result = (result * current) % mod;
            }
            current = (current * current) % mod;
            exponent >>= 1;
        }
        return result;
    }

    static long combination(int a, int b) {
        return (((factorial[a] * invFactorial[b]) % mod) * invFactorial[a - b]) % mod;
    }

    static long compute() {
        for (int i = 1; i <= n; i++) {
            factorial[i] = (factorial[i - 1] * i) % mod;
        }
        invFactorial[n] = fastPow(factorial[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            invFactorial[i] = (invFactorial[i + 1] * (i + 1)) % mod;
        }
        for (int i = 1; i <= n; i++) {
            dp[1][i] = invFactorial[i];
        }
        long answer = (dp[1][n] * combination((int)k, 1)) % mod;
        int limit = Math.min(17, (int)k);
        for (int i = 2; i <= limit; i++) {
            for (int j = n; j > 0; j = (j - 1) & n) {
                if (dp[i - 1][j] == 0) continue;
                int remaining = (int)(n ^ j);
                for (int l = remaining; l > 0; l = (l - 1) & remaining) {
                    dp[i][j + l] += dp[i - 1][j] * invFactorial[l];
                    if (dp[i][j + l] > INF) dp[i][j + l] %= mod;
                }
            }
            for (int j = n; j > 0; j = (j - 1) & n) {
                dp[i][j] %= mod;
            }
            answer += dp[i][n] * combination((int)k, i);
            answer %= mod;
        }
        answer = (answer * factorial[(int)n]) % mod;
        return answer;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        k = sc.nextLong();
        mod = sc.nextLong();
        long result = fastPow(k, n);
        if (n % 2 == 0) {
            result = (result - compute() + mod) % mod;
        }
        System.out.println(result);
        sc.close();
    }
}
